return-response.set-body:
@{
            return new JObject(
              new JProperty("type", "https://github.com/azure-intelligence-domain/integration-platform/blob/main/docs/problems/correlation-id-required.md"),
              new JProperty("title", "Correlation Id Required"),
              new JProperty("status", 400),
              new JProperty("detail", "Every call must carry a Correlation-Id header, for example ord-4711."),
              new JProperty("instance", context.Request.OriginalUrl.Path)
            ).ToString();
          }
